// api/get-doc.js
// Función serverless de Vercel: verifica la contraseña en el SERVIDOR y
// solo devuelve el HTML de la documentación si es correcta. El contenido
// nunca se descarga al navegador si la contraseña falla, porque nunca sale
// de esta función hasta que la comparación se cumple.
//
// La contraseña correcta se lee de la variable de entorno DOC_PASSWORD,
// configurada en el panel de Vercel (Project Settings → Environment
// Variables). NUNCA está escrita en este archivo ni en el repositorio.

const crypto = require('crypto');

// Contenido completo de la página de documentación. Vive únicamente dentro
// de esta función (no es un archivo estático descargable), por lo que no
// hay forma de obtenerlo sin pasar primero por la verificación de abajo.
const DOC_HTML = "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Documentaci\u00f3n t\u00e9cnica \u00b7 Diwan al-Kindi</title>\n<meta name=\"description\" content=\"Documentaci\u00f3n t\u00e9cnica del programa de cifrado y descifrado autom\u00e1tico C\u00e9sar / Atbash.\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Spectral:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --ink:#151a24;\n    --panel:#1d2433;\n    --panel-2:#242c3d;\n    --parchment:#efe7d6;\n    --parchment-2:#e4d9c1;\n    --brass:#c3924a;\n    --brass-bright:#e0ac5c;\n    --oxblood:#8a3a34;\n    --oxblood-bright:#b04b42;\n    --text-light:#ece6d8;\n    --text-muted:#a9a290;\n    --text-dark:#221c14;\n    --ok:#5f8f6b;\n    --line: rgba(236,230,216,0.14);\n  }\n  *{box-sizing:border-box;}\n  html{scroll-behavior:smooth;}\n  body{\n    margin:0;\n    background:\n      radial-gradient(1100px 600px at 15% -10%, rgba(195,146,74,0.10), transparent 60%),\n      radial-gradient(900px 500px at 100% 0%, rgba(138,58,52,0.12), transparent 55%),\n      var(--ink);\n    color:var(--text-light);\n    font-family:'Inter', sans-serif;\n    line-height:1.65;\n  }\n  .layout{\n    display:grid;\n    grid-template-columns:260px minmax(0,1fr);\n    max-width:1180px;\n    margin:0 auto;\n    gap:48px;\n    padding:48px 24px 96px;\n  }\n  @media (max-width: 880px){\n    .layout{ grid-template-columns:1fr; }\n    nav.toc{ position:static !important; order:2; }\n    main{ order:1; }\n  }\n\n  header.hero{\n    grid-column:1/-1;\n    display:flex; flex-direction:column; gap:10px;\n    padding-bottom:28px; margin-bottom:8px;\n    border-bottom:1px solid var(--line);\n  }\n  .kicker{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:12.5px; letter-spacing:.04em;\n    color:var(--brass-bright);\n  }\n  h1{\n    font-family:'Spectral', serif; font-weight:600;\n    font-size:clamp(26px,3.6vw,36px); margin:0;\n  }\n  h1 em{ font-style:italic; color:var(--brass-bright); font-weight:500; }\n  .lede{ font-size:15px; color:var(--text-muted); max-width:70ch; }\n  .hero-links{ display:flex; gap:10px; margin-top:6px; flex-wrap:wrap; }\n  .hero-links a{\n    font-family:'IBM Plex Mono', monospace; font-size:12.5px;\n    color:var(--brass-bright); text-decoration:none;\n    border:1px solid var(--line); padding:6px 12px; border-radius:6px;\n  }\n  .hero-links a:hover{ border-color:var(--brass); background:rgba(195,146,74,0.08); }\n\n  nav.toc{\n    position:sticky; top:32px; align-self:start;\n    font-size:13.5px;\n  }\n  nav.toc .label{\n    font-family:'IBM Plex Mono', monospace; font-size:11px; letter-spacing:.06em;\n    color:var(--text-muted); margin-bottom:10px;\n  }\n  nav.toc ol{ list-style:none; margin:0; padding:0; counter-reset:toc; }\n  nav.toc li{ counter-increment:toc; margin-bottom:2px; }\n  nav.toc a{\n    display:block; color:var(--text-muted); text-decoration:none;\n    padding:7px 10px; border-radius:6px; border-left:2px solid transparent;\n  }\n  nav.toc a::before{\n    content:counter(toc) \". \"; color:var(--brass-bright); font-family:'IBM Plex Mono',monospace; font-size:11px;\n  }\n  nav.toc a:hover{ color:var(--text-light); border-left-color:var(--brass); background:rgba(195,146,74,0.06); }\n\n  main section{\n    background:var(--panel);\n    border:1px solid var(--line);\n    border-radius:10px;\n    padding:28px 30px 32px;\n    margin-bottom:22px;\n    scroll-margin-top:24px;\n  }\n  main section h2{\n    font-family:'Spectral', serif; font-weight:600; font-size:22px;\n    margin:0 0 16px; display:flex; align-items:center; gap:10px;\n  }\n  main section h2 .n{\n    font-family:'IBM Plex Mono', monospace; font-size:12px; color:var(--ink);\n    background:var(--brass); width:24px; height:24px; border-radius:50%;\n    display:flex; align-items:center; justify-content:center; flex-shrink:0;\n  }\n  main section h3{\n    font-family:'Spectral', serif; font-weight:600; font-size:16.5px;\n    color:var(--brass-bright); margin:22px 0 8px;\n  }\n  p{ margin:0 0 14px; color:#dcd6c8; }\n  ul, ol.plain{ margin:0 0 14px; padding-left:22px; color:#dcd6c8; }\n  li{ margin-bottom:6px; }\n  strong{ color:var(--text-light); }\n  code{\n    font-family:'IBM Plex Mono', monospace; font-size:0.92em;\n    background:rgba(195,146,74,0.12); color:var(--brass-bright);\n    padding:1px 6px; border-radius:4px;\n  }\n  pre{\n    background:var(--ink); border:1px solid var(--line); border-radius:8px;\n    padding:16px 18px; overflow-x:auto; margin:0 0 16px;\n  }\n  pre code{ background:none; padding:0; color:#d8cfa9; font-size:13px; line-height:1.6; }\n  .formula{\n    font-family:'IBM Plex Mono', monospace; background:var(--panel-2);\n    border:1px solid var(--line); border-left:3px solid var(--brass);\n    padding:14px 18px; border-radius:6px; margin:0 0 16px; font-size:13.5px; color:#e8dfc4;\n    white-space:pre-wrap;\n  }\n  table{ width:100%; border-collapse:collapse; margin:0 0 16px; font-size:13.5px; }\n  th, td{ border:1px solid var(--line); padding:8px 12px; text-align:left; vertical-align:top; }\n  th{ font-family:'IBM Plex Mono', monospace; font-size:11.5px; color:var(--brass-bright); letter-spacing:.03em; }\n  td code{ font-size:11.5px; }\n\n  .callout{\n    border-radius:8px; padding:14px 18px; margin:0 0 16px; font-size:14px;\n  }\n  .callout.warn{ background:rgba(195,146,74,0.10); border:1px solid rgba(195,146,74,0.35); color:#f0dcb8; }\n  .callout.fix{ background:rgba(95,143,107,0.12); border:1px solid rgba(95,143,107,0.4); color:#cfe6d4; }\n\n  .status-badges{ display:flex; gap:10px; flex-wrap:wrap; margin-bottom:16px; }\n  .badge{\n    font-family:'IBM Plex Mono', monospace; font-size:12px; font-weight:600;\n    padding:6px 12px; border-radius:20px; background:var(--ink); color:var(--ok);\n    border:1px solid rgba(95,143,107,0.4);\n  }\n\n  footer{ text-align:center; font-size:12px; color:var(--text-muted); grid-column:1/-1; margin-top:16px; }\n\n  .code-toolbar{\n    display:flex; justify-content:space-between; align-items:center;\n    margin-bottom:12px; flex-wrap:wrap; gap:10px;\n  }\n  .code-toolbar .filename{\n    font-family:'IBM Plex Mono', monospace; font-size:13px; color:var(--brass-bright);\n  }\n  button.ghost{\n    font-family:'IBM Plex Mono', monospace; font-size:12.5px;\n    background:transparent; border:1px solid var(--line); color:var(--text-muted);\n    padding:7px 12px; border-radius:6px; cursor:pointer;\n  }\n  button.ghost:hover{ border-color:var(--brass); color:var(--brass-bright); }\n\n  .src-wrap{\n    background:var(--ink); border:1px solid var(--line); border-radius:8px;\n    overflow-x:auto; max-height:720px; overflow-y:auto;\n  }\n  ol.src-lines{\n    margin:0; padding:14px 0; list-style:none; counter-reset:srcline;\n    font-family:'IBM Plex Mono', monospace; font-size:12.5px; line-height:1.65;\n  }\n  ol.src-lines li{\n    counter-increment:srcline;\n    padding:0 18px 0 0;\n    white-space:pre;\n    color:#d8cfa9;\n    position:relative;\n    padding-left:56px;\n  }\n  ol.src-lines li::before{\n    content:counter(srcline);\n    position:absolute; left:0; width:42px; text-align:right;\n    color:#5a5a52; padding-right:14px; user-select:none;\n  }\n  ol.src-lines li:hover{ background:rgba(195,146,74,0.06); }\n</style>\n</head>\n<body>\n<div class=\"layout\">\n\n  <header class=\"hero\">\n    <div class=\"kicker\">\u0639\u0644\u0645 \u0627\u0644\u062a\u0639\u0645\u064a\u0629 \u2014 DOCUMENTACI\u00d3N T\u00c9CNICA</div>\n    <h1>Diwan al-Kindi <em>\u00b7 C\u00e9sar &amp; Atbash</em></h1>\n    <p class=\"lede\">Documentaci\u00f3n del programa de cifrado y descifrado autom\u00e1tico. Este archivo se entrega versionado junto al c\u00f3digo, no como capturas de pantalla ni impresiones.</p>\n    <div class=\"hero-links\">\n      <a href=\"index.html\">\u2192 Abrir el programa (index.html)</a>\n      <a href=\"README.md\">\u2192 Ver README.md en texto plano</a>\n    </div>\n  </header>\n\n  <nav class=\"toc\">\n    <div class=\"label\">CONTENIDO</div>\n    <ol>\n      <li><a href=\"#resuelve\">Qu\u00e9 resuelve el programa</a></li>\n      <li><a href=\"#porque\">Por qu\u00e9 ya no protegen nada</a></li>\n      <li><a href=\"#alkindi\">El aporte de al-Kindi</a></li>\n      <li><a href=\"#estructura\">Estructura del c\u00f3digo</a></li>\n      <li><a href=\"#validacion\">C\u00f3mo se valid\u00f3</a></li>\n      <li><a href=\"#correccion\">Correcci\u00f3n aplicada (v1\u2192v2)</a></li>\n      <li><a href=\"#publicacion\">Publicaci\u00f3n del sitio</a></li>\n      <li><a href=\"#limitaciones\">Limitaciones conocidas</a></li>\n      <li><a href=\"#codigo\">C\u00f3digo fuente completo</a></li>\n    </ol>\n  </nav>\n\n  <main>\n\n    <section id=\"resuelve\">\n      <h2><span class=\"n\">1</span>Qu\u00e9 resuelve el programa</h2>\n      <ol class=\"plain\">\n        <li>Cifra y descifra texto con <strong>C\u00e9sar</strong> (desplazamiento c\u00edclico) y <strong>Atbash</strong> (reflejo), sobre un alfabeto de trabajo que el usuario define.</li>\n        <li>El alfabeto por defecto es el conjunto de los 95 caracteres imprimibles del c\u00f3digo ASCII (32 a 126), en su propio orden \u2014 usando el c\u00f3digo ASCII como base \u2014 pero es editable para incluir s\u00edmbolos fuera de ASCII (<code>\u00f1</code>, <code>\u00e1</code>, <code>\u20ac</code>, etc.) o reducirlo a un subconjunto.</li>\n        <li>Al <strong>cifrar</strong>, el usuario elige el m\u00f3dulo (C\u00e9sar con su desplazamiento, o Atbash).</li>\n        <li>Al <strong>descifrar</strong>, el usuario <strong>no elige nada</strong>: el programa prueba todas las claves posibles y decide sola cu\u00e1l es la correcta mediante an\u00e1lisis de frecuencias, mostrando \u00fanicamente esa l\u00ednea. No hay ning\u00fan control en la interfaz para escoger el m\u00e9todo o la clave a mano.</li>\n      </ol>\n      <p>Todo el cifrado ocurre en el navegador del usuario; ning\u00fan mensaje se env\u00eda a un servidor. El archivo <code>index.html</code> no tiene dependencias externas ni backend.</p>\n    </section>\n\n    <section id=\"porque\">\n      <h2><span class=\"n\">2</span>Por qu\u00e9 C\u00e9sar y Atbash ya no protegen nada</h2>\n      <p>Ambos son cifrados por <strong>sustituci\u00f3n simple</strong>: cada s\u00edmbolo del alfabeto se reemplaza siempre por el mismo s\u00edmbolo de salida. Esa propiedad no cambia la frecuencia con la que aparece cada letra del idioma original; solo la reetiqueta. Un cifrado por sustituci\u00f3n simple tiene, como m\u00e1ximo:</p>\n      <ul>\n        <li><strong>Atbash:</strong> una sola clave posible \u2014 no hay nada que probar.</li>\n        <li><strong>C\u00e9sar:</strong> tantas claves como caracteres tenga el alfabeto (25 para el alfabeto cl\u00e1sico de 26 letras).</li>\n      </ul>\n      <p>Con un espacio de claves tan peque\u00f1o, y con tablas de frecuencia conocidas para cada idioma, cualquier texto de longitud razonable puede romperse en milisegundos \u2014 como demuestra este mismo programa. Por eso ninguno de los dos se usa hoy para proteger informaci\u00f3n sensible; sirven solo con fines did\u00e1cticos o como capa est\u00e9tica en juegos y acertijos.</p>\n    </section>\n\n    <section id=\"alkindi\">\n      <h2><span class=\"n\">3</span>El aporte de al-Kindi (criptoan\u00e1lisis por frecuencias)</h2>\n      <p>Abu Yusuf Ya'qub ibn Ishaq al-Kindi (siglo IX, Bagdad) escribi\u00f3 el <em>Risala fi Istikhraj al-Mu'amma</em> (\"Manuscrito sobre el descifrado de mensajes criptogr\u00e1ficos\"), el primer texto conocido que describe el <strong>an\u00e1lisis de frecuencias</strong>: en un texto suficientemente largo, cada letra de un idioma aparece con una frecuencia caracter\u00edstica y relativamente estable. Como la sustituci\u00f3n simple no destruye esa frecuencia \u2014solo la reetiqueta\u2014, comparar la distribuci\u00f3n de un texto candidato contra la distribuci\u00f3n esperada del idioma permite identificar la clave real sin conocerla de antemano.</p>\n      <p>El programa implementa esa idea en la funci\u00f3n <code>autoDecrypt()</code>:</p>\n      <ol class=\"plain\">\n        <li>Genera un candidato de texto plano por cada desplazamiento C\u00e9sar posible (de 1 a N\u22121, con N = tama\u00f1o del alfabeto) y un candidato m\u00e1s para Atbash.</li>\n        <li>Compara cada candidato contra un modelo de espa\u00f1ol t\u00edpico usando la prueba <strong>\u03c7\u00b2 (chi-cuadrado) de bondad de ajuste</strong> (funci\u00f3n <code>chiSquaredScore</code>).</li>\n        <li>Ordena todos los candidatos por su puntaje \u03c7\u00b2 (menor = m\u00e1s parecido al espa\u00f1ol real) y <strong>solo muestra el primero</strong>.</li>\n      </ol>\n\n      <h3>F\u00f3rmula utilizada</h3>\n      <p>El tama\u00f1o de muestra es la longitud completa del texto candidato (constante entre candidatos). Esa longitud se reparte en letras espa\u00f1olas (~80%), espacios (~18%) y otros s\u00edmbolos (~2%):</p>\n      <div class=\"formula\">esperado_categor\u00eda = longitud_total \u00d7 proporci\u00f3n_esperada_categor\u00eda\n\u03c7\u00b2 = \u03a3  (observado_categor\u00eda \u2212 esperado_categor\u00eda)\u00b2 / esperado_categor\u00eda</div>\n      <p>Se calcula sobre 27 letras espa\u00f1olas (a\u2013z + \u00f1) m\u00e1s las categor\u00edas \"espacio\" y \"otros\". Ver la secci\u00f3n 6 para el porqu\u00e9 de este dise\u00f1o.</p>\n    </section>\n\n    <section id=\"estructura\">\n      <h2><span class=\"n\">4</span>Estructura del c\u00f3digo (<code>index.html</code>)</h2>\n      <p>El archivo est\u00e1 dividido en cuatro bloques comentados dentro de la misma etiqueta <code>&lt;script&gt;</code>:</p>\n      <table>\n        <tr><th>Bloque</th><th>Funciones</th><th>Responsabilidad</th></tr>\n        <tr>\n          <td>1. Alfabeto</td>\n          <td><code>asciiPrintable</code>, <code>dedupePreserveOrder</code>, <code>getAlphabet</code>, <code>resetAlphabetAscii</code>, <code>resetAlphabetEs</code>, <code>refreshAlphabetInfo</code></td>\n          <td>Construir y validar el conjunto de caracteres de trabajo</td>\n        </tr>\n        <tr>\n          <td>2. Primitivas de cifrado</td>\n          <td><code>caesarTransform</code>, <code>caesarEncrypt</code>, <code>caesarDecrypt</code>, <code>atbash</code></td>\n          <td>Transformaciones puras sobre texto + alfabeto, reutilizables en cifrado y descifrado</td>\n        </tr>\n        <tr>\n          <td>3. Criptoan\u00e1lisis</td>\n          <td><code>SPANISH_FREQ</code>, <code>EXPECTED_SHARE</code>, <code>chiSquaredScore</code>, <code>autoDecrypt</code></td>\n          <td>Generar todos los candidatos posibles y puntuarlos por parecido al espa\u00f1ol</td>\n        </tr>\n        <tr>\n          <td>4. Interfaz</td>\n          <td><code>switchTab</code>, <code>selectEncryptMethod</code>, <code>doEncrypt</code>, <code>doAutoDecrypt</code>, <code>copyEncryptResult</code>, <code>sendToDecrypt</code></td>\n          <td>Conectar el DOM con la l\u00f3gica anterior; validaciones de UI; evitar transcripci\u00f3n manual del texto cifrado</td>\n        </tr>\n      </table>\n      <p>Las funciones de los bloques 1\u20133 son <strong>puras</strong> (no tocan el DOM), por lo que se probaron de forma aislada con Node.js antes de integrarlas a la interfaz.</p>\n\n      <h3>Caracteres fuera del alfabeto</h3>\n      <p>Cualquier car\u00e1cter del texto que <strong>no</strong> est\u00e9 en el alfabeto configurado se copia sin cambios. Esto evita que, si el usuario no incluy\u00f3 el espacio en su alfabeto personalizado, el mensaje se cifre perdiendo la separaci\u00f3n entre palabras.</p>\n    </section>\n\n    <section id=\"validacion\">\n      <h2><span class=\"n\">5</span>C\u00f3mo se valid\u00f3</h2>\n      <div class=\"status-badges\">\n        <span class=\"badge\">\u2713 Round-trip cifrar\u2192descifrar: 35/35</span>\n        <span class=\"badge\">\u2713 Auto-detecci\u00f3n frases/nombres reales: 80/80</span>\n      </div>\n      <p>Se extrajo el bloque <code>&lt;script&gt;</code> y se ejecut\u00f3 con Node.js fuera del navegador, sin ning\u00fan elemento del DOM, para comprobar:</p>\n      <ul>\n        <li>Que <code>caesarDecrypt(caesarEncrypt(texto, alfabeto, k), alfabeto, k)</code> reconstruye el texto original exacto (35 combinaciones de frases \u00d7 claves \u00d7 ambos m\u00e9todos, 0 fallas).</li>\n        <li>Que <code>autoDecrypt</code> identifica el desplazamiento C\u00e9sar exacto usado, sin que nadie lo indique, para una bater\u00eda de frases y nombres reales (8 frases \u00d7 9 desplazamientos + Atbash = 80 combinaciones, 0 fallas).</li>\n        <li>Que <code>autoDecrypt</code> distingue correctamente Atbash de un C\u00e9sar \"parecido\".</li>\n      </ul>\n    </section>\n\n    <section id=\"correccion\">\n      <h2><span class=\"n\">6</span>Correcci\u00f3n aplicada durante las pruebas (v1 \u2192 v2)</h2>\n      <div class=\"callout warn\">\n        <strong>Problema detectado:</strong> la primera versi\u00f3n de <code>chiSquaredScore</code> solo contaba las letras espa\u00f1olas encontradas en cada candidato y usaba esa cantidad como tama\u00f1o de muestra. Cada candidato tiene una cantidad distinta de letras reconocibles (el resto queda convertido en s\u00edmbolos), as\u00ed que un candidato incorrecto con muy pocas letras \"de suerte\" pod\u00eda obtener un \u03c7\u00b2 artificialmente bajo solo por tener pocos t\u00e9rminos que sumar \u2014 y ganarle al candidato correcto, sobre todo con nombres cortos como \"Emmanuel Moreno\".\n      </div>\n      <div class=\"callout fix\">\n        <strong>Correcci\u00f3n:</strong> el tama\u00f1o de muestra de <em>todos</em> los candidatos es ahora la longitud completa del texto (constante, no var\u00eda entre candidatos). Esa longitud se reparte en letras (~80%), espacios (~18%) y otros s\u00edmbolos (~2%) esperados en espa\u00f1ol t\u00edpico. Un candidato lleno de s\u00edmbolos raros queda penalizado en la categor\u00eda \"otros\" sin importar cu\u00e1ntas letras reconocibles tenga.\n      </div>\n      <p>Se agreg\u00f3 adem\u00e1s un aviso en pantalla cuando el texto cifrado tiene menos de 10 caracteres, ya que palabras sueltas muy cortas (4 letras o menos) no dan suficiente informaci\u00f3n estad\u00edstica para una detecci\u00f3n fiable \u2014 una limitaci\u00f3n real del an\u00e1lisis de frecuencias, no un defecto del c\u00f3digo (ver secci\u00f3n 8).</p>\n    </section>\n\n    <section id=\"publicacion\">\n      <h2><span class=\"n\">7</span>Publicaci\u00f3n del sitio</h2>\n      <p>El programa es un \u00fanico archivo HTML est\u00e1tico, sin backend ni dependencias externas, por lo que puede publicarse con cualquiera de estas opciones:</p>\n      <ul>\n        <li><strong>GitHub Pages</strong> (gratis): subir <code>index.html</code> a un repositorio de GitHub, activar Pages en <em>Settings \u2192 Pages \u2192 Deploy from branch</em>, y compartir la URL <code>https://usuario.github.io/repositorio/</code>.</li>\n        <li><strong>Google Sites</strong>: crear un sitio nuevo, insertar un bloque \"Insertar \u2192 Insertar c\u00f3digo\" (Embed) y pegar el contenido, o insertar el archivo alojado en otro lado como iframe.</li>\n        <li><strong>Google Apps Script (Web App)</strong>: crear un proyecto de Apps Script, pegar el HTML en un archivo <code>HtmlService</code>, y publicarlo como aplicaci\u00f3n web con <code>doGet()</code> devolviendo <code>HtmlService.createHtmlOutputFromFile(...)</code>.</li>\n      </ul>\n    </section>\n\n    <section id=\"limitaciones\">\n      <h2><span class=\"n\">8</span>Limitaciones conocidas</h2>\n      <ul>\n        <li>El an\u00e1lisis de frecuencias asume que el mensaje original est\u00e1 en <strong>espa\u00f1ol</strong> y usa letras reales del idioma. Si el alfabeto configurado no contiene letras del espa\u00f1ol, no hay forma de aplicar el an\u00e1lisis de al-Kindi y el programa lo indica en pantalla en vez de adivinar.</li>\n        <li>Palabras sueltas muy cortas (4 caracteres o menos, p. ej. \"Hola\", \"Juan\") no dan suficiente informaci\u00f3n estad\u00edstica para una detecci\u00f3n fiable; el propio al-Kindi se\u00f1alaba que el m\u00e9todo necesita texto \"suficientemente largo\". En pruebas con textos reales, a partir de unos 8 caracteres la detecci\u00f3n autom\u00e1tica ya es consistentemente correcta.</li>\n      </ul>\n    </section>\n\n    <section id=\"codigo\">\n      <h2><span class=\"n\">9</span>C\u00f3digo fuente completo (<code>index.html</code>)</h2>\n      <p>C\u00f3digo completo del programa, tal como se publica. Incluye HTML, CSS y JavaScript en un solo archivo autocontenido, sin dependencias externas.</p>\n      <div class=\"code-toolbar\">\n        <span class=\"filename\">index.html \u00b7 660 l\u00edneas</span>\n        <button class=\"ghost\" onclick=\"copySource()\" id=\"copySourceBtn\">Copiar todo el c\u00f3digo</button>\n      </div>\n      <div class=\"src-wrap\">\n        <ol class=\"src-lines\" id=\"sourceLines\">\n<li>&lt;!DOCTYPE html&gt;</li>\n<li>&lt;html lang=&quot;es&quot;&gt;</li>\n<li>&lt;head&gt;</li>\n<li>&lt;meta charset=&quot;UTF-8&quot;&gt;</li>\n<li>&lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;</li>\n<li>&lt;title&gt;Diwan al-Kindi \u00b7 Cifrado C\u00e9sar y Atbash&lt;/title&gt;</li>\n<li>&lt;meta name=&quot;description&quot; content=&quot;Herramienta educativa de cifrado y descifrado C\u00e9sar/Atbash con detecci\u00f3n autom\u00e1tica mediante an\u00e1lisis de frecuencias.&quot;&gt;</li>\n<li>&lt;link rel=&quot;preconnect&quot; href=&quot;https://fonts.googleapis.com&quot;&gt;</li>\n<li>&lt;link href=&quot;https://fonts.googleapis.com/css2?family=Spectral:wght@400;500;600;700&amp;family=IBM+Plex+Mono:wght@400;500;600&amp;family=Inter:wght@400;500;600&amp;display=swap&quot; rel=&quot;stylesheet&quot;&gt;</li>\n<li>&lt;style&gt;</li>\n<li>  :root{</li>\n<li>    --ink:#151a24;</li>\n<li>    --panel:#1d2433;</li>\n<li>    --panel-2:#242c3d;</li>\n<li>    --parchment:#efe7d6;</li>\n<li>    --parchment-2:#e4d9c1;</li>\n<li>    --brass:#c3924a;</li>\n<li>    --brass-bright:#e0ac5c;</li>\n<li>    --oxblood:#8a3a34;</li>\n<li>    --oxblood-bright:#b04b42;</li>\n<li>    --text-light:#ece6d8;</li>\n<li>    --text-muted:#a9a290;</li>\n<li>    --text-dark:#221c14;</li>\n<li>    --ok:#5f8f6b;</li>\n<li>    --line: rgba(236,230,216,0.14);</li>\n<li>  }</li>\n<li>  *{box-sizing:border-box;}</li>\n<li>  html,body{margin:0;padding:0;}</li>\n<li>  body{</li>\n<li>    background:</li>\n<li>      radial-gradient(1100px 600px at 15% -10%, rgba(195,146,74,0.10), transparent 60%),</li>\n<li>      radial-gradient(900px 500px at 100% 0%, rgba(138,58,52,0.12), transparent 55%),</li>\n<li>      var(--ink);</li>\n<li>    color:var(--text-light);</li>\n<li>    font-family:&#x27;Inter&#x27;, sans-serif;</li>\n<li>    line-height:1.5;</li>\n<li>    min-height:100vh;</li>\n<li>  }</li>\n<li>  .wrap{max-width:880px; margin:0 auto; padding:48px 24px 96px;}</li>\n<li>&#8203;</li>\n<li>  header.hero{</li>\n<li>    display:flex; flex-direction:column; gap:10px;</li>\n<li>    padding-bottom:28px; margin-bottom:36px;</li>\n<li>    border-bottom:1px solid var(--line);</li>\n<li>  }</li>\n<li>  .kicker{</li>\n<li>    font-family:&#x27;IBM Plex Mono&#x27;, monospace;</li>\n<li>    font-size:12.5px; letter-spacing:.04em;</li>\n<li>    color:var(--brass-bright);</li>\n<li>  }</li>\n<li>  h1{</li>\n<li>    font-family:&#x27;Spectral&#x27;, serif;</li>\n<li>    font-weight:600;</li>\n<li>    font-size:clamp(28px,4vw,40px);</li>\n<li>    margin:0;</li>\n<li>    color:var(--text-light);</li>\n<li>  }</li>\n<li>  h1 em{</li>\n<li>    font-style:italic; color:var(--brass-bright); font-weight:500;</li>\n<li>  }</li>\n<li>  .lede{</li>\n<li>    font-size:15.5px; color:var(--text-muted); max-width:60ch;</li>\n<li>  }</li>\n<li>&#8203;</li>\n<li>  .card{</li>\n<li>    background:var(--panel);</li>\n<li>    border:1px solid var(--line);</li>\n<li>    border-radius:10px;</li>\n<li>    padding:26px 26px 28px;</li>\n<li>    margin-bottom:22px;</li>\n<li>  }</li>\n<li>  .card h2{</li>\n<li>    font-family:&#x27;Spectral&#x27;, serif;</li>\n<li>    font-size:19px; font-weight:600; margin:0 0 4px;</li>\n<li>    display:flex; align-items:center; gap:10px;</li>\n<li>    color:var(--text-light);</li>\n<li>  }</li>\n<li>  .card h2 .n{</li>\n<li>    font-family:&#x27;IBM Plex Mono&#x27;, monospace;</li>\n<li>    font-size:12px; color:var(--ink); background:var(--brass);</li>\n<li>    width:22px; height:22px; border-radius:50%;</li>\n<li>    display:flex; align-items:center; justify-content:center;</li>\n<li>    flex-shrink:0;</li>\n<li>  }</li>\n<li>  .card .sub{ font-size:13.5px; color:var(--text-muted); margin:0 0 18px; }</li>\n<li>&#8203;</li>\n<li>  label{ display:block; font-size:13px; color:var(--text-muted); margin-bottom:6px; }</li>\n<li>  textarea, input[type=text], input[type=number], select{</li>\n<li>    width:100%;</li>\n<li>    background:var(--panel-2);</li>\n<li>    border:1px solid var(--line);</li>\n<li>    color:var(--text-light);</li>\n<li>    border-radius:7px;</li>\n<li>    padding:11px 12px;</li>\n<li>    font-family:&#x27;IBM Plex Mono&#x27;, monospace;</li>\n<li>    font-size:14px;</li>\n<li>    resize:vertical;</li>\n<li>  }</li>\n<li>  textarea:focus, input:focus, select:focus, button:focus-visible{</li>\n<li>    outline:2px solid var(--brass-bright); outline-offset:1px;</li>\n<li>  }</li>\n<li>  .row{ display:flex; gap:14px; flex-wrap:wrap; }</li>\n<li>  .row &gt; div{ flex:1; min-width:180px; }</li>\n<li>  .field{ margin-bottom:16px; }</li>\n<li>  .hint{ font-size:12px; color:var(--text-muted); margin-top:6px; }</li>\n<li>&#8203;</li>\n<li>  .tabs{ display:flex; gap:8px; margin-bottom:20px; }</li>\n<li>  .tab{</li>\n<li>    font-family:&#x27;Inter&#x27;; font-size:14px; font-weight:600;</li>\n<li>    padding:9px 18px; border-radius:7px; cursor:pointer;</li>\n<li>    background:transparent; border:1px solid var(--line); color:var(--text-muted);</li>\n<li>  }</li>\n<li>  .tab.active{ background:var(--brass); color:var(--text-dark); border-color:var(--brass); }</li>\n<li>  .panel{ display:none; }</li>\n<li>  .panel.active{ display:block; }</li>\n<li>&#8203;</li>\n<li>  .method-choice{ display:flex; gap:10px; margin-bottom:16px; }</li>\n<li>  .method-btn{</li>\n<li>    flex:1; text-align:left; padding:12px 14px; border-radius:8px;</li>\n<li>    border:1px solid var(--line); background:var(--panel-2); cursor:pointer;</li>\n<li>    color:var(--text-light);</li>\n<li>  }</li>\n<li>  .method-btn strong{ display:block; font-family:&#x27;Spectral&#x27;, serif; font-size:15px; }</li>\n<li>  .method-btn span{ font-size:12px; color:var(--text-muted); }</li>\n<li>  .method-btn.selected{ border-color:var(--brass); background:rgba(195,146,74,0.10); }</li>\n<li>&#8203;</li>\n<li>  button.action{</li>\n<li>    font-family:&#x27;Inter&#x27;; font-weight:600; font-size:14.5px;</li>\n<li>    padding:12px 22px; border-radius:7px; border:none; cursor:pointer;</li>\n<li>    background:var(--oxblood); color:#f4ece6;</li>\n<li>  }</li>\n<li>  button.action:hover{ background:var(--oxblood-bright); }</li>\n<li>  button.ghost{</li>\n<li>    font-family:&#x27;IBM Plex Mono&#x27;, monospace; font-size:12.5px;</li>\n<li>    background:transparent; border:1px solid var(--line); color:var(--text-muted);</li>\n<li>    padding:7px 12px; border-radius:6px; cursor:pointer;</li>\n<li>  }</li>\n<li>  button.ghost:hover{ border-color:var(--brass); color:var(--brass-bright); }</li>\n<li>&#8203;</li>\n<li>  .output{</li>\n<li>    margin-top:18px; background:var(--parchment); color:var(--text-dark);</li>\n<li>    border-radius:8px; padding:18px 20px; display:none;</li>\n<li>    border:1px solid var(--parchment-2);</li>\n<li>  }</li>\n<li>  .output.show{ display:block; }</li>\n<li>  .output .label{</li>\n<li>    font-family:&#x27;IBM Plex Mono&#x27;, monospace; font-size:11px; letter-spacing:.05em;</li>\n<li>    color:#7a6a4a; margin-bottom:6px;</li>\n<li>  }</li>\n<li>  .output .value{</li>\n<li>    font-family:&#x27;IBM Plex Mono&#x27;, monospace; font-size:16px; word-break:break-word;</li>\n<li>    white-space:pre-wrap;</li>\n<li>  }</li>\n<li>  .seal{</li>\n<li>    display:inline-flex; align-items:center; gap:7px;</li>\n<li>    font-family:&#x27;Inter&#x27;; font-size:12.5px; font-weight:600;</li>\n<li>    background:var(--ink); color:var(--brass-bright);</li>\n<li>    padding:5px 11px; border-radius:20px; margin-top:12px;</li>\n<li>  }</li>\n<li>  .seal .dot{ width:7px; height:7px; border-radius:50%; background:var(--brass-bright); }</li>\n<li>&#8203;</li>\n<li>  .error{</li>\n<li>    margin-top:14px; background:rgba(138,58,52,0.18); border:1px solid rgba(176,75,66,0.4);</li>\n<li>    color:#f0c9c4; border-radius:7px; padding:10px 14px; font-size:13.5px; display:none;</li>\n<li>  }</li>\n<li>  .error.show{ display:block; }</li>\n<li>&#8203;</li>\n<li>  details{ margin-top:6px; }</li>\n<li>  summary{ cursor:pointer; font-size:13px; color:var(--brass-bright); font-family:&#x27;Inter&#x27;; font-weight:600; }</li>\n<li>  details .details-body{</li>\n<li>    margin-top:12px; font-size:13.5px; color:var(--text-muted); line-height:1.65;</li>\n<li>  }</li>\n<li>  details table{ width:100%; border-collapse:collapse; margin-top:10px; font-family:&#x27;IBM Plex Mono&#x27;,monospace; font-size:12px;}</li>\n<li>  details td, details th{ border:1px solid var(--line); padding:5px 8px; text-align:left;}</li>\n<li>&#8203;</li>\n<li>  footer{</li>\n<li>    text-align:center; font-size:12px; color:var(--text-muted); margin-top:40px;</li>\n<li>  }</li>\n<li>&lt;/style&gt;</li>\n<li>&lt;/head&gt;</li>\n<li>&lt;body&gt;</li>\n<li>&lt;div class=&quot;wrap&quot;&gt;</li>\n<li>&#8203;</li>\n<li>  &lt;header class=&quot;hero&quot;&gt;</li>\n<li>    &lt;div class=&quot;kicker&quot;&gt;\u0639\u0644\u0645 \u0627\u0644\u062a\u0639\u0645\u064a\u0629 \u2014 CRIPTOGRAF\u00cdA CL\u00c1SICA&lt;/div&gt;</li>\n<li>    &lt;h1&gt;Diwan al-Kindi &lt;em&gt;\u00b7 C\u00e9sar &amp;amp; Atbash&lt;/em&gt;&lt;/h1&gt;</li>\n<li>    &lt;p class=&quot;lede&quot;&gt;Cifra y descifra mensajes con los m\u00e9todos C\u00e9sar y Atbash sobre un alfabeto que t\u00fa defines. El descifrado no pide el m\u00e9todo: lo determina solo, mediante an\u00e1lisis de frecuencias \u2014 la t\u00e9cnica descrita por primera vez por al-Kindi en el siglo IX.&lt;/p&gt;</li>\n<li>  &lt;/header&gt;</li>\n<li>&#8203;</li>\n<li>  &lt;!-- CONFIGURACI\u00d3N DE ALFABETO --&gt;</li>\n<li>  &lt;div class=&quot;card&quot;&gt;</li>\n<li>    &lt;h2&gt;&lt;span class=&quot;n&quot;&gt;1&lt;/span&gt; Conjunto de caracteres (alfabeto de trabajo)&lt;/h2&gt;</li>\n<li>    &lt;p class=&quot;sub&quot;&gt;Este es el conjunto ordenado sobre el que se calculan los desplazamientos (C\u00e9sar) y los reflejos (Atbash). Por defecto son los 95 caracteres imprimibles del c\u00f3digo ASCII (del 32 al 126), en su propio orden. Puedes editarlo: a\u00f1adir s\u00edmbolos fuera de ASCII (ej. \u00f1, \u00e1, \u20ac) o reducirlo.&lt;/p&gt;</li>\n<li>    &lt;div class=&quot;field&quot;&gt;</li>\n<li>      &lt;label for=&quot;alphabetInput&quot;&gt;Alfabeto (el orden importa)&lt;/label&gt;</li>\n<li>      &lt;textarea id=&quot;alphabetInput&quot; rows=&quot;3&quot;&gt;&lt;/textarea&gt;</li>\n<li>      &lt;div class=&quot;hint&quot; id=&quot;alphabetInfo&quot;&gt;&lt;/div&gt;</li>\n<li>    &lt;/div&gt;</li>\n<li>    &lt;div class=&quot;row&quot;&gt;</li>\n<li>      &lt;button class=&quot;ghost&quot; onclick=&quot;resetAlphabetAscii()&quot;&gt;Restaurar ASCII 32\u2013126&lt;/button&gt;</li>\n<li>      &lt;button class=&quot;ghost&quot; onclick=&quot;resetAlphabetEs()&quot;&gt;Usar alfabeto espa\u00f1ol (a\u2013z, \u00f1, may\u00fasculas, espacio)&lt;/button&gt;</li>\n<li>    &lt;/div&gt;</li>\n<li>    &lt;div class=&quot;error&quot; id=&quot;alphabetError&quot;&gt;&lt;/div&gt;</li>\n<li>  &lt;/div&gt;</li>\n<li>&#8203;</li>\n<li>  &lt;!-- TABS --&gt;</li>\n<li>  &lt;div class=&quot;tabs&quot;&gt;</li>\n<li>    &lt;button class=&quot;tab active&quot; id=&quot;tabCifrarBtn&quot; onclick=&quot;switchTab(&#x27;cifrar&#x27;)&quot;&gt;Cifrar&lt;/button&gt;</li>\n<li>    &lt;button class=&quot;tab&quot; id=&quot;tabDescifrarBtn&quot; onclick=&quot;switchTab(&#x27;descifrar&#x27;)&quot;&gt;Descifrar&lt;/button&gt;</li>\n<li>  &lt;/div&gt;</li>\n<li>&#8203;</li>\n<li>  &lt;!-- CIFRAR --&gt;</li>\n<li>  &lt;div class=&quot;panel active&quot; id=&quot;panelCifrar&quot;&gt;</li>\n<li>    &lt;div class=&quot;card&quot;&gt;</li>\n<li>      &lt;h2&gt;&lt;span class=&quot;n&quot;&gt;2&lt;/span&gt; Cifrar un mensaje&lt;/h2&gt;</li>\n<li>      &lt;p class=&quot;sub&quot;&gt;Elige el m\u00f3dulo de cifrado. Para C\u00e9sar, indica el desplazamiento (el &quot;m\u00f3dulo&quot; k).&lt;/p&gt;</li>\n<li>&#8203;</li>\n<li>      &lt;div class=&quot;method-choice&quot;&gt;</li>\n<li>        &lt;div class=&quot;method-btn selected&quot; id=&quot;btnMethodCesar&quot; onclick=&quot;selectEncryptMethod(&#x27;cesar&#x27;)&quot;&gt;</li>\n<li>          &lt;strong&gt;C\u00e9sar&lt;/strong&gt;</li>\n<li>          &lt;span&gt;Desplazamiento c\u00edclico de k posiciones dentro del alfabeto&lt;/span&gt;</li>\n<li>        &lt;/div&gt;</li>\n<li>        &lt;div class=&quot;method-btn&quot; id=&quot;btnMethodAtbash&quot; onclick=&quot;selectEncryptMethod(&#x27;atbash&#x27;)&quot;&gt;</li>\n<li>          &lt;strong&gt;Atbash&lt;/strong&gt;</li>\n<li>          &lt;span&gt;Reflejo: primer car\u00e1cter \u2194 \u00faltimo, segundo \u2194 pen\u00faltimo\u2026&lt;/span&gt;</li>\n<li>        &lt;/div&gt;</li>\n<li>      &lt;/div&gt;</li>\n<li>&#8203;</li>\n<li>      &lt;div class=&quot;field&quot; id=&quot;shiftField&quot;&gt;</li>\n<li>        &lt;label for=&quot;shiftInput&quot;&gt;Desplazamiento (m\u00f3dulo k)&lt;/label&gt;</li>\n<li>        &lt;input type=&quot;number&quot; id=&quot;shiftInput&quot; value=&quot;3&quot; min=&quot;1&quot;&gt;</li>\n<li>        &lt;div class=&quot;hint&quot; id=&quot;shiftHint&quot;&gt;&lt;/div&gt;</li>\n<li>      &lt;/div&gt;</li>\n<li>&#8203;</li>\n<li>      &lt;div class=&quot;field&quot;&gt;</li>\n<li>        &lt;label for=&quot;plainInput&quot;&gt;Mensaje a cifrar&lt;/label&gt;</li>\n<li>        &lt;textarea id=&quot;plainInput&quot; rows=&quot;3&quot; placeholder=&quot;Escribe aqu\u00ed tu mensaje...&quot;&gt;El conocimiento es poder&lt;/textarea&gt;</li>\n<li>      &lt;/div&gt;</li>\n<li>&#8203;</li>\n<li>      &lt;button class=&quot;action&quot; onclick=&quot;doEncrypt()&quot;&gt;Cifrar mensaje&lt;/button&gt;</li>\n<li>      &lt;div class=&quot;error&quot; id=&quot;encryptError&quot;&gt;&lt;/div&gt;</li>\n<li>&#8203;</li>\n<li>      &lt;div class=&quot;output&quot; id=&quot;encryptOutput&quot;&gt;</li>\n<li>        &lt;div class=&quot;label&quot;&gt;TEXTO CIFRADO&lt;/div&gt;</li>\n<li>        &lt;div class=&quot;value&quot; id=&quot;encryptResult&quot;&gt;&lt;/div&gt;</li>\n<li>        &lt;div class=&quot;seal&quot;&gt;&lt;span class=&quot;dot&quot;&gt;&lt;/span&gt;&lt;span id=&quot;encryptSeal&quot;&gt;&lt;/span&gt;&lt;/div&gt;</li>\n<li>        &lt;div class=&quot;row&quot; style=&quot;margin-top:14px;&quot;&gt;</li>\n<li>          &lt;button class=&quot;ghost&quot; onclick=&quot;copyEncryptResult()&quot; id=&quot;copyBtn&quot;&gt;Copiar texto cifrado&lt;/button&gt;</li>\n<li>          &lt;button class=&quot;ghost&quot; onclick=&quot;sendToDecrypt()&quot;&gt;Enviar a Descifrar \u2192&lt;/button&gt;</li>\n<li>        &lt;/div&gt;</li>\n<li>      &lt;/div&gt;</li>\n<li>    &lt;/div&gt;</li>\n<li>  &lt;/div&gt;</li>\n<li>&#8203;</li>\n<li>  &lt;!-- DESCIFRAR --&gt;</li>\n<li>  &lt;div class=&quot;panel&quot; id=&quot;panelDescifrar&quot;&gt;</li>\n<li>    &lt;div class=&quot;card&quot;&gt;</li>\n<li>      &lt;h2&gt;&lt;span class=&quot;n&quot;&gt;3&lt;/span&gt; Descifrar un mensaje (autom\u00e1tico)&lt;/h2&gt;</li>\n<li>      &lt;p class=&quot;sub&quot;&gt;No se selecciona el m\u00e9todo. El sistema prueba todos los desplazamientos C\u00e9sar posibles y el Atbash sobre el alfabeto configurado, mide qu\u00e9 candidato se parece m\u00e1s al espa\u00f1ol mediante la prueba \u03c7\u00b2 de frecuencias, y muestra &lt;strong&gt;solo&lt;/strong&gt; la l\u00ednea correcta.&lt;/p&gt;</li>\n<li>&#8203;</li>\n<li>      &lt;div class=&quot;field&quot;&gt;</li>\n<li>        &lt;label for=&quot;cipherInput&quot;&gt;Mensaje cifrado&lt;/label&gt;</li>\n<li>        &lt;textarea id=&quot;cipherInput&quot; rows=&quot;3&quot; placeholder=&quot;Pega aqu\u00ed el texto cifrado...&quot;&gt;&lt;/textarea&gt;</li>\n<li>      &lt;/div&gt;</li>\n<li>&#8203;</li>\n<li>      &lt;button class=&quot;action&quot; onclick=&quot;doAutoDecrypt()&quot;&gt;Descifrar autom\u00e1ticamente&lt;/button&gt;</li>\n<li>      &lt;div class=&quot;error&quot; id=&quot;decryptError&quot;&gt;&lt;/div&gt;</li>\n<li>&#8203;</li>\n<li>      &lt;div class=&quot;output&quot; id=&quot;decryptOutput&quot;&gt;</li>\n<li>        &lt;div class=&quot;label&quot;&gt;TEXTO DESCIFRADO&lt;/div&gt;</li>\n<li>        &lt;div class=&quot;value&quot; id=&quot;decryptResult&quot;&gt;&lt;/div&gt;</li>\n<li>        &lt;div class=&quot;seal&quot;&gt;&lt;span class=&quot;dot&quot;&gt;&lt;/span&gt;&lt;span id=&quot;decryptSeal&quot;&gt;&lt;/span&gt;&lt;/div&gt;</li>\n<li>      &lt;/div&gt;</li>\n<li>      &lt;div class=&quot;error&quot; id=&quot;shortTextWarning&quot; style=&quot;background:rgba(195,146,74,0.14); border-color:rgba(195,146,74,0.4); color:#f0dcb8;&quot;&gt;&lt;/div&gt;</li>\n<li>&#8203;</li>\n<li>      &lt;details&gt;</li>\n<li>        &lt;summary&gt;Ver c\u00f3mo decidi\u00f3 el sistema (an\u00e1lisis de al-Kindi)&lt;/summary&gt;</li>\n<li>        &lt;div class=&quot;details-body&quot; id=&quot;analysisDetails&quot;&gt;</li>\n<li>          A\u00fan no se ha ejecutado ning\u00fan descifrado.</li>\n<li>        &lt;/div&gt;</li>\n<li>      &lt;/details&gt;</li>\n<li>    &lt;/div&gt;</li>\n<li>  &lt;/div&gt;</li>\n<li>&#8203;</li>\n<li>  &lt;footer&gt;</li>\n<li>    Herramienta educativa \u00b7 Los cifrados C\u00e9sar y Atbash son sustituciones simples,</li>\n<li>    vulnerables al an\u00e1lisis de frecuencias desde el siglo IX. No usar para proteger informaci\u00f3n real.</li>\n<li>  &lt;/footer&gt;</li>\n<li>&lt;/div&gt;</li>\n<li>&#8203;</li>\n<li>&lt;script&gt;</li>\n<li>/* ======================================================================</li>\n<li>   1. ALFABETO DE TRABAJO</li>\n<li>   ====================================================================== */</li>\n<li>&#8203;</li>\n<li>function asciiPrintable(){</li>\n<li>  let s = &quot;&quot;;</li>\n<li>  for (let c = 32; c &lt;= 126; c++) s += String.fromCharCode(c);</li>\n<li>  return s;</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>function dedupePreserveOrder(str){</li>\n<li>  const seen = new Set();</li>\n<li>  let out = &quot;&quot;;</li>\n<li>  for (const ch of str){</li>\n<li>    if (!seen.has(ch)){ seen.add(ch); out += ch; }</li>\n<li>  }</li>\n<li>  return out;</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>function getAlphabet(){</li>\n<li>  return dedupePreserveOrder(document.getElementById(&#x27;alphabetInput&#x27;).value);</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>function resetAlphabetAscii(){</li>\n<li>  document.getElementById(&#x27;alphabetInput&#x27;).value = asciiPrintable();</li>\n<li>  refreshAlphabetInfo();</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>function resetAlphabetEs(){</li>\n<li>  const es = &quot;abcdefghijklmn\u00f1opqrstuvwxyzABCDEFGHIJKLMN\u00d1OPQRSTUVWXYZ &quot;;</li>\n<li>  document.getElementById(&#x27;alphabetInput&#x27;).value = es;</li>\n<li>  refreshAlphabetInfo();</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>function refreshAlphabetInfo(){</li>\n<li>  const a = getAlphabet();</li>\n<li>  document.getElementById(&#x27;alphabetInfo&#x27;).textContent =</li>\n<li>    `${a.length} caracteres \u00fanicos configurados. Los desplazamientos C\u00e9sar v\u00e1lidos van de 1 a ${Math.max(a.length-1,0)}.`;</li>\n<li>  document.getElementById(&#x27;shiftHint&#x27;).textContent =</li>\n<li>    `Debe ser un entero entre 1 y ${Math.max(a.length-1,1)} (equivalente al residuo mod ${a.length}).`;</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>document.getElementById(&#x27;alphabetInput&#x27;).addEventListener(&#x27;input&#x27;, refreshAlphabetInfo);</li>\n<li>resetAlphabetAscii();</li>\n<li>&#8203;</li>\n<li>/* ======================================================================</li>\n<li>   2. PRIMITIVAS DE CIFRADO: C\u00c9SAR Y ATBASH SOBRE UN ALFABETO ARBITRARIO</li>\n<li>   ====================================================================== */</li>\n<li>&#8203;</li>\n<li>// Desplaza cada car\u00e1cter presente en &#x27;alphabet&#x27; por &#x27;shift&#x27; posiciones</li>\n<li>// (mod N). Caracteres que no pertenecen al alfabeto se dejan intactos,</li>\n<li>// para no destruir separadores que el usuario decidi\u00f3 no incluir.</li>\n<li>function caesarTransform(text, alphabet, shift){</li>\n<li>  const N = alphabet.length;</li>\n<li>  if (N === 0) return text;</li>\n<li>  const index = new Map();</li>\n<li>  for (let i = 0; i &lt; N; i++) index.set(alphabet[i], i);</li>\n<li>  const mod = ((shift % N) + N) % N;</li>\n<li>  let out = &quot;&quot;;</li>\n<li>  for (const ch of text){</li>\n<li>    if (index.has(ch)){</li>\n<li>      const newIdx = (index.get(ch) + mod) % N;</li>\n<li>      out += alphabet[newIdx];</li>\n<li>    } else {</li>\n<li>      out += ch;</li>\n<li>    }</li>\n<li>  }</li>\n<li>  return out;</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>function caesarEncrypt(text, alphabet, shift){ return caesarTransform(text, alphabet, shift); }</li>\n<li>function caesarDecrypt(text, alphabet, shift){ return caesarTransform(text, alphabet, -shift); }</li>\n<li>&#8203;</li>\n<li>// Atbash: refleja la posici\u00f3n dentro del alfabeto (N-1-i). Es su propia inversa.</li>\n<li>function atbash(text, alphabet){</li>\n<li>  const N = alphabet.length;</li>\n<li>  if (N === 0) return text;</li>\n<li>  const index = new Map();</li>\n<li>  for (let i = 0; i &lt; N; i++) index.set(alphabet[i], i);</li>\n<li>  let out = &quot;&quot;;</li>\n<li>  for (const ch of text){</li>\n<li>    if (index.has(ch)){</li>\n<li>      out += alphabet[N - 1 - index.get(ch)];</li>\n<li>    } else {</li>\n<li>      out += ch;</li>\n<li>    }</li>\n<li>  }</li>\n<li>  return out;</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>/* ======================================================================</li>\n<li>   3. CRIPTOAN\u00c1LISIS AUTOM\u00c1TICO (M\u00c9TODO DE AL-KINDI: AN\u00c1LISIS DE FRECUENCIAS)</li>\n<li>   ------------------------------------------------------------------------</li>\n<li>   Al-Kindi (Abu Yusuf Ya&#x27;qub ibn Ishaq al-Kindi, s. IX) fue el primero en</li>\n<li>   describir, en su &quot;Risala fi Istikhraj al-Mu&#x27;amma&quot; (Manuscrito sobre el</li>\n<li>   descifrado de mensajes criptogr\u00e1ficos), que en un texto suficientemente</li>\n<li>   largo cada letra del idioma aparece con una frecuencia caracter\u00edstica y</li>\n<li>   estable. Un cifrado por sustituci\u00f3n simple no destruye esa frecuencia:</li>\n<li>   solo la reetiqueta. Comparando la distribuci\u00f3n de un texto candidato</li>\n<li>   contra la distribuci\u00f3n esperada del idioma, se puede identificar la</li>\n<li>   clave correcta sin conocerla de antemano, y sin que una persona tenga</li>\n<li>   que &quot;elegir a ojo&quot; cu\u00e1l candidato es el correcto.</li>\n<li>&#8203;</li>\n<li>   Aqu\u00ed se implementa esa idea con una prueba de bondad de ajuste \u03c7\u00b2:</li>\n<li>   para cada candidato de descifrado se cuenta cu\u00e1ntas veces aparece cada</li>\n<li>   letra espa\u00f1ola y se compara contra el conteo esperado seg\u00fan la</li>\n<li>   frecuencia est\u00e1ndar del idioma. El candidato con menor \u03c7\u00b2 (m\u00e1s parecido</li>\n<li>   al espa\u00f1ol real) se declara ganador, de forma enteramente autom\u00e1tica.</li>\n<li>   ====================================================================== */</li>\n<li>&#8203;</li>\n<li>// Frecuencias relativas (%) de las letras en espa\u00f1ol (fuente: estudios de</li>\n<li>// frecuencia l\u00e9xica del espa\u00f1ol; valores de referencia est\u00e1ndar).</li>\n<li>const SPANISH_FREQ = {</li>\n<li>  a: 12.53, b: 1.42, c: 4.68, d: 5.86, e: 13.68, f: 0.69, g: 1.01, h: 0.70,</li>\n<li>  i: 6.25, j: 0.44, k: 0.02, l: 4.97, m: 3.15, n: 6.71, &quot;\u00f1&quot;: 0.31, o: 8.68,</li>\n<li>  p: 2.51, q: 0.88, r: 6.87, s: 7.98, t: 4.63, u: 3.93, v: 0.90, w: 0.02,</li>\n<li>  x: 0.22, y: 0.90, z: 0.52</li>\n<li>};</li>\n<li>&#8203;</li>\n<li>const ACCENT_MAP = { \u00e1:&#x27;a&#x27;, \u00e9:&#x27;e&#x27;, \u00ed:&#x27;i&#x27;, \u00f3:&#x27;o&#x27;, \u00fa:&#x27;u&#x27;, \u00fc:&#x27;u&#x27;,</li>\n<li>                      \u00c1:&#x27;a&#x27;, \u00c9:&#x27;e&#x27;, \u00cd:&#x27;i&#x27;, \u00d3:&#x27;o&#x27;, \u00da:&#x27;u&#x27;, \u00dc:&#x27;u&#x27; };</li>\n<li>&#8203;</li>\n<li>// --- Modelo de un texto &quot;t\u00edpico&quot; en espa\u00f1ol, sobre TODOS sus caracteres ---</li>\n<li>// No basta con comparar solo las letras encontradas: cada candidato de</li>\n<li>// descifrado tiene una cantidad distinta de letras reconocibles (el resto</li>\n<li>// queda convertido en s\u00edmbolos), as\u00ed que un candidato incorrecto con muy</li>\n<li>// pocas letras --pero much\u00edsimos s\u00edmbolos raros-- pod\u00eda obtener antes un</li>\n<li>// chi-cuadrado artificialmente bajo solo por tener pocos t\u00e9rminos que sumar.</li>\n<li>// Para evitarlo, el &quot;tama\u00f1o de muestra&quot; de todos los candidatos es siempre</li>\n<li>// el mismo: la longitud completa del texto. Se reparte esa longitud en tres</li>\n<li>// categor\u00edas con una frecuencia esperada cada una: letras espa\u00f1olas, espacio</li>\n<li>// y &quot;otros&quot; (d\u00edgitos, puntuaci\u00f3n, s\u00edmbolos). Un candidato lleno de s\u00edmbolos</li>\n<li>// raros queda fuertemente penalizado en la categor\u00eda &quot;otros&quot;, sin importar</li>\n<li>// cu\u00e1ntas letras &quot;de suerte&quot; tenga.</li>\n<li>const SPACE_SHARE = 0.18;   // proporci\u00f3n t\u00edpica de espacios en prosa en espa\u00f1ol</li>\n<li>const OTHER_SHARE = 0.02;   // proporci\u00f3n t\u00edpica de d\u00edgitos/puntuaci\u00f3n/s\u00edmbolos</li>\n<li>const LETTER_SHARE = 1 - SPACE_SHARE - OTHER_SHARE; // resto: letras</li>\n<li>&#8203;</li>\n<li>// Frecuencia esperada de cada letra espa\u00f1ola como fracci\u00f3n del texto COMPLETO</li>\n<li>// (no solo de las letras), para que sea comparable entre candidatos.</li>\n<li>const EXPECTED_SHARE = {};</li>\n<li>for (const letter in SPANISH_FREQ){</li>\n<li>  EXPECTED_SHARE[letter] = (SPANISH_FREQ[letter] / 100) * LETTER_SHARE;</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>function normalizeChar(ch){</li>\n<li>  return ACCENT_MAP[ch] ? ACCENT_MAP[ch] : ch;</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>// Estad\u00edstico chi-cuadrado entre la distribuci\u00f3n observada de TODO el texto</li>\n<li>// (letras + espacios + otros) y la esperada para espa\u00f1ol t\u00edpico. Menor</li>\n<li>// valor = m\u00e1s parecido al espa\u00f1ol. El tama\u00f1o de muestra es fijo (longitud</li>\n<li>// del texto), igual para todos los candidatos, as\u00ed que s\u00ed son comparables.</li>\n<li>function chiSquaredScore(text){</li>\n<li>  const total = text.length;</li>\n<li>  if (total === 0) return { score: Infinity, sample: 0 };</li>\n<li>&#8203;</li>\n<li>  const letterCounts = {};</li>\n<li>  let spaceCount = 0;</li>\n<li>  let letterTotal = 0;</li>\n<li>&#8203;</li>\n<li>  for (const raw of text){</li>\n<li>    if (raw === &#x27; &#x27;){</li>\n<li>      spaceCount++;</li>\n<li>      continue;</li>\n<li>    }</li>\n<li>    const lower = normalizeChar(raw).toLowerCase();</li>\n<li>    if (Object.prototype.hasOwnProperty.call(SPANISH_FREQ, lower)){</li>\n<li>      letterCounts[lower] = (letterCounts[lower] || 0) + 1;</li>\n<li>      letterTotal++;</li>\n<li>    }</li>\n<li>  }</li>\n<li>  const otherCount = total - letterTotal - spaceCount;</li>\n<li>&#8203;</li>\n<li>  let chi = 0;</li>\n<li>  for (const letter in EXPECTED_SHARE){</li>\n<li>    const expected = total * EXPECTED_SHARE[letter];</li>\n<li>    const observed = letterCounts[letter] || 0;</li>\n<li>    if (expected &gt; 0) chi += Math.pow(observed - expected, 2) / expected;</li>\n<li>  }</li>\n<li>  const expectedSpace = total * SPACE_SHARE;</li>\n<li>  if (expectedSpace &gt; 0) chi += Math.pow(spaceCount - expectedSpace, 2) / expectedSpace;</li>\n<li>&#8203;</li>\n<li>  const expectedOther = total * OTHER_SHARE;</li>\n<li>  if (expectedOther &gt; 0) chi += Math.pow(otherCount - expectedOther, 2) / expectedOther;</li>\n<li>&#8203;</li>\n<li>  return { score: chi, sample: total };</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>// Prueba TODOS los desplazamientos C\u00e9sar posibles (1..N-1) m\u00e1s Atbash sobre</li>\n<li>// el alfabeto activo, punt\u00faa cada candidato y devuelve \u00fanicamente el mejor.</li>\n<li>// Esta es la funci\u00f3n que garantiza que &quot;no interviene el factor humano&quot;:</li>\n<li>// no hay men\u00fa para que el usuario escoja el m\u00e9todo o la clave.</li>\n<li>function autoDecrypt(ciphertext, alphabet){</li>\n<li>  const N = alphabet.length;</li>\n<li>  if (N &lt; 2) throw new Error(&quot;El alfabeto necesita al menos 2 caracteres.&quot;);</li>\n<li>&#8203;</li>\n<li>  const candidates = [];</li>\n<li>&#8203;</li>\n<li>  for (let shift = 1; shift &lt; N; shift++){</li>\n<li>    const plain = caesarDecrypt(ciphertext, alphabet, shift);</li>\n<li>    const { score, sample } = chiSquaredScore(plain);</li>\n<li>    candidates.push({ type: &quot;C\u00e9sar&quot;, shift, plain, score, sample });</li>\n<li>  }</li>\n<li>&#8203;</li>\n<li>  {</li>\n<li>    const plain = atbash(ciphertext, alphabet);</li>\n<li>    const { score, sample } = chiSquaredScore(plain);</li>\n<li>    candidates.push({ type: &quot;Atbash&quot;, shift: null, plain, score, sample });</li>\n<li>  }</li>\n<li>&#8203;</li>\n<li>  candidates.sort((a, b) =&gt; a.score - b.score);</li>\n<li>  return candidates; // el primero (\u00edndice 0) es el ganador</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>/* ======================================================================</li>\n<li>   4. INTERFAZ</li>\n<li>   ====================================================================== */</li>\n<li>&#8203;</li>\n<li>let encryptMethod = &#x27;cesar&#x27;;</li>\n<li>&#8203;</li>\n<li>function switchTab(name){</li>\n<li>  document.getElementById(&#x27;panelCifrar&#x27;).classList.toggle(&#x27;active&#x27;, name === &#x27;cifrar&#x27;);</li>\n<li>  document.getElementById(&#x27;panelDescifrar&#x27;).classList.toggle(&#x27;active&#x27;, name === &#x27;descifrar&#x27;);</li>\n<li>  document.getElementById(&#x27;tabCifrarBtn&#x27;).classList.toggle(&#x27;active&#x27;, name === &#x27;cifrar&#x27;);</li>\n<li>  document.getElementById(&#x27;tabDescifrarBtn&#x27;).classList.toggle(&#x27;active&#x27;, name === &#x27;descifrar&#x27;);</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>function selectEncryptMethod(method){</li>\n<li>  encryptMethod = method;</li>\n<li>  document.getElementById(&#x27;btnMethodCesar&#x27;).classList.toggle(&#x27;selected&#x27;, method === &#x27;cesar&#x27;);</li>\n<li>  document.getElementById(&#x27;btnMethodAtbash&#x27;).classList.toggle(&#x27;selected&#x27;, method === &#x27;atbash&#x27;);</li>\n<li>  document.getElementById(&#x27;shiftField&#x27;).style.display = (method === &#x27;cesar&#x27;) ? &#x27;block&#x27; : &#x27;none&#x27;;</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>function showError(id, msg){</li>\n<li>  const el = document.getElementById(id);</li>\n<li>  el.textContent = msg;</li>\n<li>  el.classList.add(&#x27;show&#x27;);</li>\n<li>}</li>\n<li>function hideError(id){</li>\n<li>  document.getElementById(id).classList.remove(&#x27;show&#x27;);</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>function doEncrypt(){</li>\n<li>  hideError(&#x27;encryptError&#x27;);</li>\n<li>  document.getElementById(&#x27;encryptOutput&#x27;).classList.remove(&#x27;show&#x27;);</li>\n<li>&#8203;</li>\n<li>  const alphabet = getAlphabet();</li>\n<li>  const text = document.getElementById(&#x27;plainInput&#x27;).value;</li>\n<li>&#8203;</li>\n<li>  if (alphabet.length &lt; 2){</li>\n<li>    showError(&#x27;encryptError&#x27;, &#x27;El alfabeto debe tener al menos 2 caracteres distintos.&#x27;);</li>\n<li>    return;</li>\n<li>  }</li>\n<li>  if (!text){</li>\n<li>    showError(&#x27;encryptError&#x27;, &#x27;Escribe un mensaje para cifrar.&#x27;);</li>\n<li>    return;</li>\n<li>  }</li>\n<li>&#8203;</li>\n<li>  let result, sealText;</li>\n<li>  if (encryptMethod === &#x27;cesar&#x27;){</li>\n<li>    const shift = parseInt(document.getElementById(&#x27;shiftInput&#x27;).value, 10);</li>\n<li>    if (!Number.isInteger(shift) || shift &lt; 1 || shift &gt; alphabet.length - 1){</li>\n<li>      showError(&#x27;encryptError&#x27;, `El desplazamiento debe ser un entero entre 1 y ${alphabet.length - 1}.`);</li>\n<li>      return;</li>\n<li>    }</li>\n<li>    result = caesarEncrypt(text, alphabet, shift);</li>\n<li>    sealText = `M\u00f3dulo: C\u00e9sar \u00b7 desplazamiento = ${shift} (mod ${alphabet.length})`;</li>\n<li>  } else {</li>\n<li>    result = atbash(text, alphabet);</li>\n<li>    sealText = `M\u00f3dulo: Atbash \u00b7 alfabeto de ${alphabet.length} caracteres`;</li>\n<li>  }</li>\n<li>&#8203;</li>\n<li>  document.getElementById(&#x27;encryptResult&#x27;).textContent = result;</li>\n<li>  document.getElementById(&#x27;encryptSeal&#x27;).textContent = sealText;</li>\n<li>  document.getElementById(&#x27;encryptOutput&#x27;).classList.add(&#x27;show&#x27;);</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>function doAutoDecrypt(){</li>\n<li>  hideError(&#x27;decryptError&#x27;);</li>\n<li>  document.getElementById(&#x27;decryptOutput&#x27;).classList.remove(&#x27;show&#x27;);</li>\n<li>&#8203;</li>\n<li>  const alphabet = getAlphabet();</li>\n<li>  const cipher = document.getElementById(&#x27;cipherInput&#x27;).value;</li>\n<li>&#8203;</li>\n<li>  if (alphabet.length &lt; 2){</li>\n<li>    showError(&#x27;decryptError&#x27;, &#x27;El alfabeto debe tener al menos 2 caracteres distintos.&#x27;);</li>\n<li>    return;</li>\n<li>  }</li>\n<li>  if (!cipher){</li>\n<li>    showError(&#x27;decryptError&#x27;, &#x27;Pega un mensaje cifrado.&#x27;);</li>\n<li>    return;</li>\n<li>  }</li>\n<li>&#8203;</li>\n<li>  let ranked;</li>\n<li>  try{</li>\n<li>    ranked = autoDecrypt(cipher, alphabet);</li>\n<li>  } catch(e){</li>\n<li>    showError(&#x27;decryptError&#x27;, e.message);</li>\n<li>    return;</li>\n<li>  }</li>\n<li>&#8203;</li>\n<li>  const winner = ranked[0];</li>\n<li>&#8203;</li>\n<li>  if (!isFinite(winner.score) || cipher.length === 0){</li>\n<li>    showError(&#x27;decryptError&#x27;, &#x27;No se pudo identificar el cifrado autom\u00e1ticamente. Verifica que el alfabeto configurado sea el mismo que se us\u00f3 para cifrar, y que el texto cifrado no tenga caracteres de m\u00e1s o de menos (c\u00f3pialo y p\u00e9galo en vez de teclearlo).&#x27;);</li>\n<li>    return;</li>\n<li>  }</li>\n<li>&#8203;</li>\n<li>  document.getElementById(&#x27;decryptResult&#x27;).textContent = winner.plain;</li>\n<li>  document.getElementById(&#x27;decryptSeal&#x27;).textContent = winner.type === &#x27;C\u00e9sar&#x27;</li>\n<li>    ? `Detectado: C\u00e9sar \u00b7 desplazamiento = ${winner.shift} (mod ${alphabet.length})`</li>\n<li>    : `Detectado: Atbash`;</li>\n<li>  document.getElementById(&#x27;decryptOutput&#x27;).classList.add(&#x27;show&#x27;);</li>\n<li>&#8203;</li>\n<li>  const shortTextWarning = document.getElementById(&#x27;shortTextWarning&#x27;);</li>\n<li>  if (cipher.length &lt; 10){</li>\n<li>    shortTextWarning.textContent = &#x27;Este texto es muy corto para un an\u00e1lisis de frecuencias totalmente fiable (al-Kindi ya se\u00f1alaba que se necesita texto suficientemente largo). Con menos de ~10 caracteres, el resultado puede no ser el correcto. Prueba con una oraci\u00f3n m\u00e1s larga si el resultado no coincide con lo esperado.&#x27;;</li>\n<li>    shortTextWarning.classList.add(&#x27;show&#x27;);</li>\n<li>  } else {</li>\n<li>    shortTextWarning.classList.remove(&#x27;show&#x27;);</li>\n<li>  }</li>\n<li>&#8203;</li>\n<li>  // Panel de transparencia del an\u00e1lisis (no es un selector: solo explica</li>\n<li>  // por qu\u00e9 se eligi\u00f3 autom\u00e1ticamente ese candidato).</li>\n<li>  const top5 = ranked.slice(0, 5).map((c, i) =&gt;</li>\n<li>    `&lt;tr&gt;&lt;td&gt;${i+1}&lt;/td&gt;&lt;td&gt;${c.type}${c.shift !== null ? &#x27; (k=&#x27; + c.shift + &#x27;)&#x27; : &#x27;&#x27;}&lt;/td&gt;&lt;td&gt;${c.score.toFixed(2)}&lt;/td&gt;&lt;td&gt;${c.sample}&lt;/td&gt;&lt;/tr&gt;`</li>\n<li>  ).join(&#x27;&#x27;);</li>\n<li>&#8203;</li>\n<li>  document.getElementById(&#x27;analysisDetails&#x27;).innerHTML = `</li>\n<li>    Se generaron ${ranked.length} candidatos (uno por cada desplazamiento C\u00e9sar de 1 a ${alphabet.length - 1}, m\u00e1s Atbash).</li>\n<li>    Cada candidato se compar\u00f3 contra un modelo de espa\u00f1ol t\u00edpico (letras + espacios + otros s\u00edmbolos, en las proporciones</li>\n<li>    en que aparecen normalmente en un texto) usando la prueba \u03c7\u00b2 de bondad de ajuste, sobre el texto completo del</li>\n<li>    candidato. Menor \u03c7\u00b2 indica mayor parecido con el espa\u00f1ol natural. El candidato ganador tuvo \u03c7\u00b2 = ${winner.score.toFixed(2)}</li>\n<li>    sobre ${winner.sample} caracteres.</li>\n<li>    &lt;table&gt;</li>\n<li>      &lt;tr&gt;&lt;th&gt;#&lt;/th&gt;&lt;th&gt;Candidato&lt;/th&gt;&lt;th&gt;\u03c7\u00b2 (menor = mejor)&lt;/th&gt;&lt;th&gt;Caracteres analizados&lt;/th&gt;&lt;/tr&gt;</li>\n<li>      ${top5}</li>\n<li>    &lt;/table&gt;</li>\n<li>  `;</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>// Copia el texto cifrado y env\u00eda directo a la pesta\u00f1a Descifrar, para</li>\n<li>// evitar que alguien tenga que teclearlo o copiarlo a mano (fuente com\u00fan</li>\n<li>// de errores de transcripci\u00f3n, como caracteres repetidos de m\u00e1s o de menos).</li>\n<li>function copyEncryptResult(){</li>\n<li>  const text = document.getElementById(&#x27;encryptResult&#x27;).textContent;</li>\n<li>  navigator.clipboard.writeText(text).then(() =&gt; {</li>\n<li>    const btn = document.getElementById(&#x27;copyBtn&#x27;);</li>\n<li>    const original = btn.textContent;</li>\n<li>    btn.textContent = &#x27;\u00a1Copiado!&#x27;;</li>\n<li>    setTimeout(() =&gt; { btn.textContent = original; }, 1500);</li>\n<li>  }).catch(() =&gt; {</li>\n<li>    showError(&#x27;encryptError&#x27;, &#x27;No se pudo copiar autom\u00e1ticamente; selecciona y copia el texto manualmente.&#x27;);</li>\n<li>  });</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>function sendToDecrypt(){</li>\n<li>  const text = document.getElementById(&#x27;encryptResult&#x27;).textContent;</li>\n<li>  document.getElementById(&#x27;cipherInput&#x27;).value = text;</li>\n<li>  switchTab(&#x27;descifrar&#x27;);</li>\n<li>}</li>\n<li>&#8203;</li>\n<li>// Inicializa el estado del formulario de cifrado</li>\n<li>selectEncryptMethod(&#x27;cesar&#x27;);</li>\n<li>&lt;/script&gt;</li>\n<li>&lt;/body&gt;</li>\n<li>&lt;/html&gt;</li>\n        </ol>\n      </div>\n    </section>\n\n  </main>\n\n  <footer>Diwan al-Kindi \u00b7 Documentaci\u00f3n t\u00e9cnica \u00b7 Herramienta educativa, no apta para proteger informaci\u00f3n real.</footer>\n</div>\n<script>\nfunction copySource(){\n  const items = document.querySelectorAll('#sourceLines li');\n  const text = Array.from(items).map(li => li.textContent).join('\\n');\n  navigator.clipboard.writeText(text).then(() => {\n    const btn = document.getElementById('copySourceBtn');\n    const original = btn.textContent;\n    btn.textContent = '\u00a1Copiado!';\n    setTimeout(() => { btn.textContent = original; }, 1500);\n  }).catch(() => {\n    alert('No se pudo copiar autom\u00e1ticamente. Selecciona el bloque de c\u00f3digo manualmente.');\n  });\n}\n</script>\n</body>\n</html>\n";

// Comparación en tiempo constante para no filtrar, por la duración de la
// respuesta, cuántos caracteres de la contraseña acertó quien la intente.
function safeCompare(a, b) {
  const bufA = Buffer.from(String(a));
  const bufB = Buffer.from(String(b));
  if (bufA.length !== bufB.length) {
    // Igual se hace una comparación de longitud equivalente para no
    // delatar por timing que la longitud ya estaba mal.
    crypto.timingSafeEqual(bufA, bufA);
    return false;
  }
  return crypto.timingSafeEqual(bufA, bufB);
}

// Límite simple de intentos por IP en memoria (se reinicia si la función
// "duerme"; es una capa extra, no un reemplazo de un límite real con base
// de datos, pero ayuda contra intentos automatizados básicos).
const attempts = new Map();
const MAX_ATTEMPTS = 10;
const WINDOW_MS = 10 * 60 * 1000; // 10 minutos

function isRateLimited(ip) {
  const now = Date.now();
  const record = attempts.get(ip);
  if (!record || now - record.first > WINDOW_MS) {
    attempts.set(ip, { count: 1, first: now });
    return false;
  }
  record.count++;
  return record.count > MAX_ATTEMPTS;
}

module.exports = (req, res) => {
  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    return res.status(405).json({ error: 'Método no permitido.' });
  }

  const ip = (req.headers['x-forwarded-for'] || req.socket.remoteAddress || 'unknown').split(',')[0].trim();
  if (isRateLimited(ip)) {
    return res.status(429).json({ error: 'Demasiados intentos. Espera unos minutos e intenta de nuevo.' });
  }

  const correctPassword = process.env.DOC_PASSWORD;
  if (!correctPassword) {
    // Falta configurar la variable de entorno en Vercel.
    return res.status(500).json({ error: 'El servidor no tiene configurada la contraseña (DOC_PASSWORD). Revisa las variables de entorno del proyecto en Vercel.' });
  }

  const password = req.body && req.body.password;
  if (typeof password !== 'string' || password.length === 0) {
    return res.status(400).json({ error: 'Falta la contraseña.' });
  }

  if (!safeCompare(password, correctPassword)) {
    return res.status(401).json({ error: 'Contraseña incorrecta.' });
  }

  return res.status(200).json({ html: DOC_HTML });
};
